HIERARCHY = {
    'root': ['platform', 'workloads'],
    'platform': ['sub-identity', 'sub-connectivity'],
    'workloads': ['corp', 'online'],
    'corp': ['sub-erp'],
    'online': ['sub-web'],
}
SUBSCRIPTIONS = ['sub-identity', 'sub-connectivity', 'sub-erp', 'sub-web']

def find_path(target, node='root'):
    if node == target:
        return [node]
    for child in HIERARCHY.get(node, []):
        sub = find_path(target, child)
        if sub is not None:
            return [node] + sub
    return None

for sub in SUBSCRIPTIONS:
    print(f"{sub}: {' > '.join(find_path(sub))}")
